function setup() {
	pixelDensity(1);

	let canvas = createCanvas(
		max(windowWidth, windowHeight),
		max(windowWidth, windowHeight),
		WEBGL);

	shaderTexture = createGraphics(width, height, WEBGL);
	shaderTexture.noStroke();
}

function draw() {
	background(0);
	translate(-width / 2, -height / 2);
	noStroke();

	// Display shader.
	shaderTexture.shader(shaderTest);

	//define variables here:
	shaderTest.setUniform("iResolution", [width, height]);
	shaderTest.setUniform("iTime", frameCount / 100);
	shaderTest.setUniform("iMouse", [(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))]);

	shaderTexture.rect(0, 0, width, height);
	texture(shaderTexture);
	rect(0, 0, width, height);
}

// === Tab: FragShader ===
let fragShader = `
	precision highp float;

	//call variables here:
	uniform vec2 iResolution;
	uniform float iTime;
	uniform vec2 iMouse;

	void main() {
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = gl_FragCoord.xy/iResolution;

    // Time varying pixel color
    vec3 col = 0.5 + 0.5*cos(iTime+uv.xyx+vec3(0,2,4));

    // Output to screen
		gl_FragColor = vec4(col, 1.0);
	}
`;

// === Tab: VertShader ===
let vertShader = `
	precision highp float;

	attribute vec3 aPosition;

	void main() {
		vec4 positionVec4 = vec4(aPosition, 1.0);
		positionVec4.xy = positionVec4.xy * 2.0 - 1.0;
		gl_Position = positionVec4;
	}
`;

